  public static func add(SOURCE_STANDARD: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SOURCE_STANDARD, at: VT.SOURCE_STANDARD) }
  public static func endVCFSubject(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createVCFSubject(
    _ fbb: inout FlatBufferBuilder,
    PEER_IDOffset PEER_ID: Offset = Offset(),
    DNOffset DN: Offset = Offset(),
    PROFILE_CIDOffset PROFILE_CID: Offset = Offset(),
    PROFILE_SHA256Offset PROFILE_SHA256: Offset = Offset(),
    PROFILE_SIGNATUREOffset PROFILE_SIGNATURE: Offset = Offset(),
    PROFILE_SIGNATURE_ALGORITHMOffset PROFILE_SIGNATURE_ALGORITHM: Offset = Offset(),
    PROFILE_SIGNATURE_TIMESTAMP: Int64 = 0,
    SIGNING_PUBLIC_KEYOffset SIGNING_PUBLIC_KEY: Offset = Offset(),
    ENCRYPTION_PUBLIC_KEYOffset ENCRYPTION_PUBLIC_KEY: Offset = Offset(),
    SOURCE_STANDARDOffset SOURCE_STANDARD: Offset = Offset()
  ) -> Offset {
    let __start = VCFSubject.startVCFSubject(&fbb)
    VCFSubject.add(PEER_ID: PEER_ID, &fbb)
    VCFSubject.add(DN: DN, &fbb)
    VCFSubject.add(PROFILE_CID: PROFILE_CID, &fbb)
    VCFSubject.add(PROFILE_SHA256: PROFILE_SHA256, &fbb)
    VCFSubject.add(PROFILE_SIGNATURE: PROFILE_SIGNATURE, &fbb)
    VCFSubject.add(PROFILE_SIGNATURE_ALGORITHM: PROFILE_SIGNATURE_ALGORITHM, &fbb)
    VCFSubject.add(PROFILE_SIGNATURE_TIMESTAMP: PROFILE_SIGNATURE_TIMESTAMP, &fbb)
    VCFSubject.add(SIGNING_PUBLIC_KEY: SIGNING_PUBLIC_KEY, &fbb)
    VCFSubject.add(ENCRYPTION_PUBLIC_KEY: ENCRYPTION_PUBLIC_KEY, &fbb)
    VCFSubject.add(SOURCE_STANDARD: SOURCE_STANDARD, &fbb)
    return VCFSubject.endVCFSubject(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.PEER_ID, fieldName: "PEER_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.DN, fieldName: "DN", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROFILE_CID, fieldName: "PROFILE_CID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROFILE_SHA256, fieldName: "PROFILE_SHA256", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROFILE_SIGNATURE, fieldName: "PROFILE_SIGNATURE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROFILE_SIGNATURE_ALGORITHM, fieldName: "PROFILE_SIGNATURE_ALGORITHM", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROFILE_SIGNATURE_TIMESTAMP, fieldName: "PROFILE_SIGNATURE_TIMESTAMP", required: false, type: Int64.self)
    try _v.visit(field: VT.SIGNING_PUBLIC_KEY, fieldName: "SIGNING_PUBLIC_KEY", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ENCRYPTION_PUBLIC_KEY, fieldName: "ENCRYPTION_PUBLIC_KEY", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SOURCE_STANDARD, fieldName: "SOURCE_STANDARD", required: false, type: ForwardOffset<String>.self)
    _v.finish()
  }
}

///  Everything needed to decide whether this card is servable, and whether two
///  implementations produced the same bytes.
public struct VCFConformance: FlatBufferTable, FlatbuffersVectorInitializable, Verifiable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$VCF" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: VCFConformance.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let VERSION: VOffset = 4
    static let PROFILE: VOffset = 6
    static let LINE_ENDING: VOffset = 8
    static let FOLD_OCTET_WIDTH: VOffset = 10
    static let BYTE_LENGTH: VOffset = 12
    static let UNFOLDED_BYTE_LENGTH: VOffset = 14
    static let BYTE_BUDGET: VOffset = 16
    static let WITHIN_BYTE_BUDGET: VOffset = 18
    static let CARD_SHA256: VOffset = 20
    static let PROPERTY_COUNT: VOffset = 22
    static let CARRIES_VERIFICATION_CHAIN: VOffset = 24
  }

  ///  Card format version token verbatim as emitted, e.g. `3.0`.
  public var VERSION: String! { let o = _accessor.offset(VT.VERSION); return _accessor.string(at: o) }
  public var VERSIONSegmentArray: [UInt8]! { return _accessor.getVector(at: VT.VERSION) }
  ///  Identifier of the emission profile the card conforms to, verbatim, naming
  ///  the annex revision the publisher implemented.
  public var PROFILE: String? { let o = _accessor.offset(VT.PROFILE); return o == 0 ? nil : _accessor.string(at: o) }
  public var PROFILESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.PROFILE) }
  ///  Line terminator the card text uses.
  public var LINE_ENDING: vcfLineEnding { let o = _accessor.offset(VT.LINE_ENDING); return o == 0 ? .unspecified : vcfLineEnding(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unspecified }
  ///  Octet width beyond which a content line is folded onto continuation lines.
  ///  0 means the publisher folded nothing, which is non-canonical.
  public var FOLD_OCTET_WIDTH: UInt32 { let o = _accessor.offset(VT.FOLD_OCTET_WIDTH); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Octet length of `CARD` exactly as emitted, folding and terminators
  ///  included. This is the number a serving surface budgets against.
  public var BYTE_LENGTH: UInt32 { let o = _accessor.offset(VT.BYTE_LENGTH); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Octet length the same card would have with folding removed. Carried so a
  ///  folding disagreement is detectable without unfolding the text.
  public var UNFOLDED_BYTE_LENGTH: UInt32 { let o = _accessor.offset(VT.UNFOLDED_BYTE_LENGTH); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Octet ceiling of the surface this card was produced for. 0 means the
  ///  publisher states no ceiling; it never means a ceiling of zero.
  public var BYTE_BUDGET: UInt32 { let o = _accessor.offset(VT.BYTE_BUDGET); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Whether BYTE_LENGTH is within BYTE_BUDGET. False with a non-zero budget
  ///  means the card is a valid record that is NOT servable on that surface.
  public var WITHIN_BYTE_BUDGET: Bool { let o = _accessor.offset(VT.WITHIN_BYTE_BUDGET); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  ///  SHA-256 of `CARD` as 64 lowercase hexadecimal characters. This is the
  ///  value two implementations compare to prove byte-identical projection.
  public var CARD_SHA256: String? { let o = _accessor.offset(VT.CARD_SHA256); return o == 0 ? nil : _accessor.string(at: o) }
  public var CARD_SHA256SegmentArray: [UInt8]? { return _accessor.getVector(at: VT.CARD_SHA256) }
  ///  Number of property rows emitted, unfolded. Carried so a truncated card is
  ///  detectable before parsing.
  public var PROPERTY_COUNT: UInt32 { let o = _accessor.offset(VT.PROPERTY_COUNT); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Whether the card carries a complete verification chain: a signing-key row,
  ///  an encryption-key row, and a profile-signature row, all present in the
  ///  UNFOLDED text. A card without all three cannot verify its own subject and
  ///  is not servable as an identity card.
  public var CARRIES_VERIFICATION_CHAIN: Bool { let o = _accessor.offset(VT.CARRIES_VERIFICATION_CHAIN); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  public static func startVCFConformance(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 11) }
  public static func add(VERSION: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: VERSION, at: VT.VERSION) }
  public static func add(PROFILE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PROFILE, at: VT.PROFILE) }
  public static func add(LINE_ENDING: vcfLineEnding, _ fbb: inout FlatBufferBuilder) { fbb.add(element: LINE_ENDING.rawValue, def: 0, at: VT.LINE_ENDING) }
  public static func add(FOLD_OCTET_WIDTH: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: FOLD_OCTET_WIDTH, def: 0, at: VT.FOLD_OCTET_WIDTH) }
  public static func add(BYTE_LENGTH: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: BYTE_LENGTH, def: 0, at: VT.BYTE_LENGTH) }
  public static func add(UNFOLDED_BYTE_LENGTH: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: UNFOLDED_BYTE_LENGTH, def: 0, at: VT.UNFOLDED_BYTE_LENGTH) }
  public static func add(BYTE_BUDGET: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: BYTE_BUDGET, def: 0, at: VT.BYTE_BUDGET) }
  public static func add(WITHIN_BYTE_BUDGET: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: WITHIN_BYTE_BUDGET, def: false,
   at: VT.WITHIN_BYTE_BUDGET) }
  public static func add(CARD_SHA256: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CARD_SHA256, at: VT.CARD_SHA256) }
  public static func add(PROPERTY_COUNT: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: PROPERTY_COUNT, def: 0, at: VT.PROPERTY_COUNT) }
  public static func add(CARRIES_VERIFICATION_CHAIN: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CARRIES_VERIFICATION_CHAIN, def: false,
   at: VT.CARRIES_VERIFICATION_CHAIN) }
  public static func endVCFConformance(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [4]); return end }
  public static func createVCFConformance(
    _ fbb: inout FlatBufferBuilder,
    VERSIONOffset VERSION: Offset,
    PROFILEOffset PROFILE: Offset = Offset(),
    LINE_ENDING: vcfLineEnding = .unspecified,
    FOLD_OCTET_WIDTH: UInt32 = 0,
    BYTE_LENGTH: UInt32 = 0,
    UNFOLDED_BYTE_LENGTH: UInt32 = 0,
    BYTE_BUDGET: UInt32 = 0,
    WITHIN_BYTE_BUDGET: Bool = false,
    CARD_SHA256Offset CARD_SHA256: Offset = Offset(),
    PROPERTY_COUNT: UInt32 = 0,
    CARRIES_VERIFICATION_CHAIN: Bool = false
  ) -> Offset {
    let __start = VCFConformance.startVCFConformance(&fbb)
    VCFConformance.add(VERSION: VERSION, &fbb)
    VCFConformance.add(PROFILE: PROFILE, &fbb)
    VCFConformance.add(LINE_ENDING: LINE_ENDING, &fbb)
    VCFConformance.add(FOLD_OCTET_WIDTH: FOLD_OCTET_WIDTH, &fbb)
    VCFConformance.add(BYTE_LENGTH: BYTE_LENGTH, &fbb)
    VCFConformance.add(UNFOLDED_BYTE_LENGTH: UNFOLDED_BYTE_LENGTH, &fbb)
    VCFConformance.add(BYTE_BUDGET: BYTE_BUDGET, &fbb)
    VCFConformance.add(WITHIN_BYTE_BUDGET: WITHIN_BYTE_BUDGET, &fbb)
    VCFConformance.add(CARD_SHA256: CARD_SHA256, &fbb)
    VCFConformance.add(PROPERTY_COUNT: PROPERTY_COUNT, &fbb)
    VCFConformance.add(CARRIES_VERIFICATION_CHAIN: CARRIES_VERIFICATION_CHAIN, &fbb)
    return VCFConformance.endVCFConformance(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.VERSION, fieldName: "VERSION", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROFILE, fieldName: "PROFILE", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.LINE_ENDING, fieldName: "LINE_ENDING", required: false, type: vcfLineEnding.self)
    try _v.visit(field: VT.FOLD_OCTET_WIDTH, fieldName: "FOLD_OCTET_WIDTH", required: false, type: UInt32.self)
    try _v.visit(field: VT.BYTE_LENGTH, fieldName: "BYTE_LENGTH", required: false, type: UInt32.self)
    try _v.visit(field: VT.UNFOLDED_BYTE_LENGTH, fieldName: "UNFOLDED_BYTE_LENGTH", required: false, type: UInt32.self)
    try _v.visit(field: VT.BYTE_BUDGET, fieldName: "BYTE_BUDGET", required: false, type: UInt32.self)
    try _v.visit(field: VT.WITHIN_BYTE_BUDGET, fieldName: "WITHIN_BYTE_BUDGET", required: false, type: Bool.self)
    try _v.visit(field: VT.CARD_SHA256, fieldName: "CARD_SHA256", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PROPERTY_COUNT, fieldName: "PROPERTY_COUNT", required: false, type: UInt32.self)
    try _v.visit(field: VT.CARRIES_VERIFICATION_CHAIN, fieldName: "CARRIES_VERIFICATION_CHAIN", required: false, type: Bool.self)
    _v.finish()
  }
}

///  vCard Projection Card
public struct VCF: FlatBufferTable, FlatbuffersVectorInitializable, Verifiable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$VCF" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: VCF.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let CARD_ID: VOffset = 4
    static let FORM: VOffset = 6
    static let CARD: VOffset = 8
    static let MEDIA_TYPE: VOffset = 10
    static let SUBJECT: VOffset = 12
    static let PROPERTIES: VOffset = 14
    static let ALIASES: VOffset = 16
    static let PHOTO_POLICY: VOffset = 18
    static let PHOTO_URI: VOffset = 20
    static let PHOTO_MEDIA_TYPE: VOffset = 22
    static let CONFORMANCE: VOffset = 24
    static let PRODUCER_ID: VOffset = 26
    static let PRODUCER_VERSION: VOffset = 28
    static let GENERATED_AT: VOffset = 30
    static let EXPIRES_AT: VOffset = 32
    static let TAGS: VOffset = 34
    static let NOTES: VOffset = 36
  }

  ///  Publisher-stable identifier of this card. Together with the publishing key
  ///  it is the card's identity across every republication.
  public var CARD_ID: String? { let o = _accessor.offset(VT.CARD_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var CARD_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.CARD_ID) }
  ///  Which canonical emission form this record carries.
  public var FORM: vcfCardForm { let o = _accessor.offset(VT.FORM); return o == 0 ? .unspecified : vcfCardForm(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unspecified }
  ///  The emitted card text VERBATIM: every octet an importer will read,
  ///  including folding and line terminators. Authoritative over PROPERTIES and
  ///  ALIASES in every disagreement.
  public var CARD: String! { let o = _accessor.offset(VT.CARD); return _accessor.string(at: o) }
  public var CARDSegmentArray: [UInt8]! { return _accessor.getVector(at: VT.CARD) }
  ///  Media type the card is served as, verbatim, including its charset
  ///  parameter.
  public var MEDIA_TYPE: String? { let o = _accessor.offset(VT.MEDIA_TYPE); return o == 0 ? nil : _accessor.string(at: o) }
  public var MEDIA_TYPESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.MEDIA_TYPE) }
  ///  The profile this card projects and the provenance binding them.
  public var SUBJECT: VCFSubject? { let o = _accessor.offset(VT.SUBJECT); return o == 0 ? nil : VCFSubject(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  The publisher's parse of `CARD`, in canonical emission order.
  public var PROPERTIES: FlatbufferVector<VCFProperty> { return _accessor.vector(at: VT.PROPERTIES, byteSize: 4) }
  ///  The identity address rows carried by `CARD`, in canonical emission order.
  public var ALIASES: FlatbufferVector<VCFAlias> { return _accessor.vector(at: VT.ALIASES, byteSize: 4) }
  ///  How the card carries a portrait, if at all.
  public var PHOTO_POLICY: vcfPhotoPolicy { let o = _accessor.offset(VT.PHOTO_POLICY); return o == 0 ? .unspecified : vcfPhotoPolicy(rawValue: _accessor.readBuffer(of: Int8.self, at: o)) ?? .unspecified }
  ///  Locator of the portrait content under URI_REFERENCE, verbatim as emitted.
  ///  Empty under every other policy.
  public var PHOTO_URI: String? { let o = _accessor.offset(VT.PHOTO_URI); return o == 0 ? nil : _accessor.string(at: o) }
  public var PHOTO_URISegmentArray: [UInt8]? { return _accessor.getVector(at: VT.PHOTO_URI) }
  ///  Media type of the portrait content verbatim, when one is carried.
  public var PHOTO_MEDIA_TYPE: String? { let o = _accessor.offset(VT.PHOTO_MEDIA_TYPE); return o == 0 ? nil : _accessor.string(at: o) }
  public var PHOTO_MEDIA_TYPESegmentArray: [UInt8]? { return _accessor.getVector(at: VT.PHOTO_MEDIA_TYPE) }
  ///  Emission facts and the digest two implementations compare.
  public var CONFORMANCE: VCFConformance? { let o = _accessor.offset(VT.CONFORMANCE); return o == 0 ? nil : VCFConformance(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  ///  Reverse-DNS identifier of the component that produced the card, so two
  ///  projectors are distinguishable when their bytes differ.
  public var PRODUCER_ID: String? { let o = _accessor.offset(VT.PRODUCER_ID); return o == 0 ? nil : _accessor.string(at: o) }
  public var PRODUCER_IDSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.PRODUCER_ID) }
  ///  Build or release identifier of that component verbatim.
  public var PRODUCER_VERSION: String? { let o = _accessor.offset(VT.PRODUCER_VERSION); return o == 0 ? nil : _accessor.string(at: o) }
  public var PRODUCER_VERSIONSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.PRODUCER_VERSION) }
  ///  RFC 3339 UTC fixed-millisecond timestamp at which the card was projected.
  public var GENERATED_AT: String? { let o = _accessor.offset(VT.GENERATED_AT); return o == 0 ? nil : _accessor.string(at: o) }
  public var GENERATED_ATSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.GENERATED_AT) }
  ///  RFC 3339 UTC fixed-millisecond timestamp after which a consumer re-projects
  ///  from the profile rather than serving this card. Empty means no expiry.
  public var EXPIRES_AT: String? { let o = _accessor.offset(VT.EXPIRES_AT); return o == 0 ? nil : _accessor.string(at: o) }
  public var EXPIRES_ATSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.EXPIRES_AT) }
  ///  `namespace:value` facets, sorted and deduplicated. See TAG GRAMMAR above.
  public var TAGS: FlatbufferVector<String?> { return _accessor.vector(at: VT.TAGS, byteSize: 4) }
  ///  Publisher note about this card; never a substitute for a field.
  public var NOTES: String? { let o = _accessor.offset(VT.NOTES); return o == 0 ? nil : _accessor.string(at: o) }
  public var NOTESSegmentArray: [UInt8]? { return _accessor.getVector(at: VT.NOTES) }
  public static func startVCF(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 17) }
  public static func add(CARD_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CARD_ID, at: VT.CARD_ID) }
  public static func add(FORM: vcfCardForm, _ fbb: inout FlatBufferBuilder) { fbb.add(element: FORM.rawValue, def: 0, at: VT.FORM) }
  public static func add(CARD: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CARD, at: VT.CARD) }
  public static func add(MEDIA_TYPE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: MEDIA_TYPE, at: VT.MEDIA_TYPE) }
  public static func add(SUBJECT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: SUBJECT, at: VT.SUBJECT) }
  public static func addVectorOf(PROPERTIES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PROPERTIES, at: VT.PROPERTIES) }
  public static func addVectorOf(ALIASES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ALIASES, at: VT.ALIASES) }
  public static func add(PHOTO_POLICY: vcfPhotoPolicy, _ fbb: inout FlatBufferBuilder) { fbb.add(element: PHOTO_POLICY.rawValue, def: 0, at: VT.PHOTO_POLICY) }
  public static func add(PHOTO_URI: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PHOTO_URI, at: VT.PHOTO_URI) }
  public static func add(PHOTO_MEDIA_TYPE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PHOTO_MEDIA_TYPE, at: VT.PHOTO_MEDIA_TYPE) }
  public static func add(CONFORMANCE: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: CONFORMANCE, at: VT.CONFORMANCE) }
  public static func add(PRODUCER_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PRODUCER_ID, at: VT.PRODUCER_ID) }
  public static func add(PRODUCER_VERSION: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: PRODUCER_VERSION, at: VT.PRODUCER_VERSION) }
  public static func add(GENERATED_AT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: GENERATED_AT, at: VT.GENERATED_AT) }
  public static func add(EXPIRES_AT: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: EXPIRES_AT, at: VT.EXPIRES_AT) }
  public static func addVectorOf(TAGS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: TAGS, at: VT.TAGS) }
  public static func add(NOTES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: NOTES, at: VT.NOTES) }
  public static func endVCF(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); fbb.require(table: end, fields: [8]); return end }
  public static func createVCF(
    _ fbb: inout FlatBufferBuilder,
    CARD_IDOffset CARD_ID: Offset = Offset(),
    FORM: vcfCardForm = .unspecified,
    CARDOffset CARD: Offset,
    MEDIA_TYPEOffset MEDIA_TYPE: Offset = Offset(),
    SUBJECTOffset SUBJECT: Offset = Offset(),
    PROPERTIESVectorOffset PROPERTIES: Offset = Offset(),
    ALIASESVectorOffset ALIASES: Offset = Offset(),
    PHOTO_POLICY: vcfPhotoPolicy = .unspecified,
    PHOTO_URIOffset PHOTO_URI: Offset = Offset(),
    PHOTO_MEDIA_TYPEOffset PHOTO_MEDIA_TYPE: Offset = Offset(),
    CONFORMANCEOffset CONFORMANCE: Offset = Offset(),
    PRODUCER_IDOffset PRODUCER_ID: Offset = Offset(),
    PRODUCER_VERSIONOffset PRODUCER_VERSION: Offset = Offset(),
    GENERATED_ATOffset GENERATED_AT: Offset = Offset(),
    EXPIRES_ATOffset EXPIRES_AT: Offset = Offset(),
    TAGSVectorOffset TAGS: Offset = Offset(),
    NOTESOffset NOTES: Offset = Offset()
  ) -> Offset {
    let __start = VCF.startVCF(&fbb)
    VCF.add(CARD_ID: CARD_ID, &fbb)
    VCF.add(FORM: FORM, &fbb)
    VCF.add(CARD: CARD, &fbb)
    VCF.add(MEDIA_TYPE: MEDIA_TYPE, &fbb)
    VCF.add(SUBJECT: SUBJECT, &fbb)
    VCF.addVectorOf(PROPERTIES: PROPERTIES, &fbb)
